import fractions,hashlib,json,math,os,pathlib,re,signal,subprocess,sys,time
ROOT=pathlib.Path('<isolated-media-worktree>')
REV='6279c1f57fb268945ea9567643eb8e4331411091'
OUT=pathlib.Path('<owned-validation-artifact>')
INITIAL=pathlib.Path('<unused-prior-artifact>')
INNER='--inside-lock' in sys.argv
if not INNER:OUT.mkdir(mode=0o700)
os.umask(0o077)
os.environ['GIT_OPTIONAL_LOCKS']='0'
