signal.signal(signal.SIGTERM,interrupted);signal.signal(signal.SIGINT,interrupted)
def digest(path):
 with pathlib.Path(path).open('rb') as stream:return hashlib.file_digest(stream,'sha256').hexdigest()
def source():
 assert subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True,timeout=10).strip()==REV
 assert not subprocess.check_output(['git','--no-optional-locks','status','--porcelain'],cwd=ROOT,text=True,timeout=10).strip()
def exists(group):
 try:os.killpg(group,0);return True
 except ProcessLookupError:return False
def save():
 j={'source':REV,'scope':'frame_receipt_clock_and_restart' if INNER else 'supervisor_queue','steps':steps,'helperSha256':digest(__file__),'limits':'Corrected in evidence scope; original helper contained stale copied descriptive metadata.'}
 if INNER:j['cases']=cases
 else:j['nativeResults']='native-results.json'
 (OUT/('native-results.json' if INNER else 'queue.json')).write_text(json.dumps(j,indent=2)+'\n')
def run(name,command,deadline,grace=4):
 source();started=time.monotonic();pending=None;cleanup=[]
 with (OUT/(name+'.log')).open('x') as log:
  child=subprocess.Popen(command,cwd=ROOT,env=ENV,stdout=log,stderr=subprocess.STDOUT,start_new_session=True)
  try:code=child.wait(timeout=deadline)
  except subprocess.TimeoutExpired:code=124
  except BaseException as error:code=130;pending=error
  finally:
   if child.poll() is None:
    try:os.killpg(child.pid,signal.SIGTERM)
    except ProcessLookupError:pass
    cleanup.append('SIGTERM')
    try:child.wait(timeout=grace)
    except subprocess.TimeoutExpired:
     try:os.killpg(child.pid,signal.SIGKILL)
     except ProcessLookupError:pass
     cleanup.append('SIGKILL');child.wait(timeout=3)
   if exists(child.pid):
    try:os.killpg(child.pid,signal.SIGKILL)
    except ProcessLookupError:pass
    cleanup.append('SIGKILL-descendants')
   until=time.monotonic()+3
   while exists(child.pid) and time.monotonic()<until:time.sleep(.05)
 source();steps.append({'name':name,'command':command,'deadlineSeconds':deadline,'pid':child.pid,'pgid':child.pid,'exitCode':code,'childExitCode':child.returncode,'seconds':round(time.monotonic()-started,3),'groupGone':not exists(child.pid),'cleanupSignals':cleanup,'sourceCleanBefore':True,'sourceCleanAfter':True,'logSha256':digest(OUT/(name+'.log'))});save();assert not exists(child.pid)
 if pending:raise pending
 return code


