   assert run(label,['cargo','test','--locked','--manifest-path','media/Cargo.toml','--features','webrtc','--lib','-j2','-q',selected,'--','--exact','--nocapture'],45)==0
   assert 'test result: ok. 1 passed; 0 failed; 0 ignored;' in (OUT/(label+'.log')).read_text()
  assert run('strict-clippy',['cargo','clippy','--locked','--manifest-path','media/Cargo.toml','--features','webrtc','--lib','--tests','--examples','-j2','-q','--message-format=short','--','-D','warnings'],600)==0
  assert run('diff-check',['git','diff','--check','cee1a49e32e10517bad96fbbcde3214ebfca8ea6',REV],15)==0
  code=0
except BaseException:
 save();raise
